from collections import deque

class Limiter:
    def __init__(self, window, limit):
        if window <= 0 or isinstance(limit, bool) or not isinstance(limit, int) or limit <= 0:
            raise ValueError('invalid limits')
        self.window, self.limit = window, limit
        self.events = {}
    def allow(self, key, now):
        events = self.events.setdefault(key, deque())
        while events and events[0] <= now - self.window: events.popleft()
        if len(events) >= self.limit: return False
        events.append(now)
        return True

