from itertools import islice

def chunks(iterable, size):
    if isinstance(size, bool) or not isinstance(size, int) or size <= 0:
        raise ValueError('invalid size')
    iterator = iter(iterable)
    while True:
        batch = list(islice(iterator, size))
        if not batch: return
        yield batch

