import Foundation

func compareVersions(_ left: String, _ right: String) -> Int? {
    guard let first = Int(left.replacingOccurrences(of: ".", with: "")), let second = Int(right.replacingOccurrences(of: ".", with: "")) else { return nil }
    return first == second ? 0 : first < second ? -1 : 1
}

