func compareVersions(_ left: String, _ right: String) -> Int? {
    func parts(_ input: String) -> [String]? {
        let items = input.split(separator: ".", omittingEmptySubsequences: false).map(String.init)
        guard items.count == 3, items.allSatisfy({ item in
            !item.isEmpty && item.allSatisfy { $0 >= "0" && $0 <= "9" } && (item == "0" || !item.hasPrefix("0"))
        }) else { return nil }
        return items
    }
    guard let lhs = parts(left), let rhs = parts(right) else { return nil }
    for (a, b) in zip(lhs, rhs) where a != b {
        if a.count != b.count { return a.count < b.count ? -1 : 1 }
        return a < b ? -1 : 1
    }
    return 0
}
